// Example policy sketch for APIM quotas per-tenant (pseudo)
processRequest(ctx){
  const tenant = ctx.request.headers['X-Tenant-ID'];
  const used = redis.incr(`quota:${tenant}`);
  if(used > MAX_TENANT_QUOTA) throw new Error('Quota exceeded');
}
```

